// `FEATURES_HI`, RO: feature bits 32 to 63.
#define RGFX_REG_FEATURES_HI 12

// `STATUS`, RW: writing [`RGFX_STATUS_RESET`] resets the device; the guest writes
// [`RGFX_STATUS_DRIVER_READY`] once it has read the rings' headers.
